const money=n=>Math.round(n).toLocaleString('ru-RU')+' ₽';const monthsText=n=>`${Math.floor(n/12)?Math.floor(n/12)+' г. ':''}${n%12?n%12+' мес.':''}`.trim()||'0 мес.';let extras=[],lastSchedule=[];const $=s=>document.querySelector(s),form=$('#loan-form'),dialog=$('#extra-dialog'),extraForm=$('#extra-form'),list=$('#extra-list');
function annuity(balance,rate,months){if(months<=0)return balance;if(!rate)return balance/months;const q=(1+rate)**months;return balance*rate*q/(q-1)}function applies(e,m){return e.kind==='once'?m===e.start:m>=e.start&&m<=e.end&&(m-e.start)%e.frequency===0}function extraFor(m){return extras.filter(e=>applies(e,m)).reduce((s,e)=>s+e.amount,0)}function actionFor(m){return extras.filter(e=>applies(e,m)).at(-1)?.action||'term'}
function simulate(p,useExtras){let bal=p.amount,interestTotal=0,paidTotal=0,extraTotal=0,rows=[],payment=annuity(bal,p.annual/1200,p.months),principalFixed=p.amount/p.months;const start=new Date($('#start-date').value+'T12:00:00');for(let m=1;m<=1200&&bal>.01;m++){const rate=p.annual/1200,interest=bal*rate;let planned=p.type==='annuity'?payment:principalFixed+interest;let principal=Math.max(0,Math.min(bal,planned-interest));let extra=useExtras?Math.max(0,Math.min(bal-principal,extraFor(m))):0;let total=interest+principal+extra;bal=Math.max(0,bal-principal-extra);interestTotal+=interest;paidTotal+=total;extraTotal+=extra;const d=new Date(start);d.setMonth(d.getMonth()+m);rows.push({m,date:d.toLocaleDateString('ru-RU',{month:'2-digit',year:'numeric'}),payment:interest+principal,principal,interest,extra,balance:bal});if(extra&&actionFor(m)==='payment'&&bal>0){const remain=Math.max(1,p.months-m);payment=annuity(bal,rate,remain);principalFixed=bal/remain}if(!useExtras&&m>=p.months)break;if(useExtras&&!extras.length&&m>=p.months)break}return{payment:rows[0]?.payment||0,interestTotal,paidTotal,extraTotal,months:rows.length,rows}}
function params(){return{amount:+$('#amount').value,annual:+$('#rate').value,months:+$('#term').value,type:$('[name=payment-type]:checked').value}}function calculate(){const p=params();if(!p.amount||!p.months)return;const now=simulate(p,true),base=simulate(p,false);lastSchedule=now.rows;$('#monthly-payment').textContent=money(now.payment);$('#payment-note').textContent=p.type==='annuity'?'аннуитетный платеж':'первый дифференцированный платеж';$('#interest-total').textContent=money(now.interestTotal);$('#extra-total').textContent=money(now.extraTotal);$('#actual-term').textContent=monthsText(now.months);$('#total-paid').textContent=money(now.paidTotal);const save=Math.max(0,base.interestTotal-now.interestTotal),savedMonths=Math.max(0,base.months-now.months);$('#interest-saving').textContent=money(save);$('#months-saving').textContent=monthsText(savedMonths);let text=extras.length?`Досрочно будет внесено ${money(now.extraTotal)}. Ориентировочная экономия на процентах — ${money(save)}.`:'Добавьте досрочный платеж, чтобы сравнить его с исходным графиком.';if(savedMonths)text+=` Срок сократится примерно на ${monthsText(savedMonths)}.`;$('#simple-explanation').textContent=text;renderRows(now.rows);renderChart(now.rows);$('#schedule-section').hidden=false}
function renderExtras(){if(!extras.length){list.innerHTML='<div class="empty-extra"><p>Добавьте разовый или регулярный досрочный платеж.</p></div>';return}list.innerHTML=extras.map((e,i)=>`<div class="extra-row"><i>${e.kind==='once'?'1×':'↻'}</i><span><b>${money(e.amount)} · с ${e.start}-го месяца</b><small>${e.kind==='regular'?'каждые '+e.frequency+' мес. до '+e.end+'-го':'разовый'} · ${e.action==='term'?'уменьшить срок':'уменьшить платеж'}</small></span><button type="button" data-remove="${i}">Удалить</button></div>`).join('');list.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{extras.splice(+b.dataset.remove,1);renderExtras();calculate()})}function renderRows(rows,extraOnly=false){$('#schedule-body').innerHTML=rows.filter(r=>!extraOnly||r.extra).map(r=>`<tr><td>${r.m}</td><td>${r.date}</td><td>${money(r.payment)}</td><td>${money(r.principal)}</td><td>${money(r.interest)}</td><td class="extra-cell">${r.extra?money(r.extra):'—'}</td><td>${money(r.balance)}</td></tr>`).join('')}function renderChart(rows){const step=Math.max(1,Math.ceil(rows.length/72)),data=rows.filter((_,i)=>i%step===0),max=Math.max(...data.map(r=>r.payment+r.extra));$('#chart-bars').innerHTML=data.map(r=>{const k=220/max;return`<div class="chart-col" title="${r.date}: ${money(r.payment+r.extra)}"><i class="extra" style="height:${r.extra*k}px"></i><i class="principal" style="height:${r.principal*k}px"></i><i class="interest" style="height:${r.interest*k}px"></i></div>`}).join('')}
form.onsubmit=e=>{e.preventDefault();calculate()};form.onreset=()=>setTimeout(()=>{extras=[];renderExtras();$('#schedule-section').hidden=true},0);$('#add-extra').onclick=()=>dialog.showModal();$('.close-btn').onclick=()=>dialog.close();extraForm.onchange=()=>extraForm.classList.toggle('is-regular',extraForm.kind.value==='regular');extraForm.onsubmit=e=>{e.preventDefault();extras.push({kind:extraForm.kind.value,amount:+extraForm['extra-amount'].value,start:+extraForm['extra-start'].value,frequency:+extraForm['extra-frequency'].value,end:+extraForm['extra-end'].value,action:extraForm.action.value});dialog.close();renderExtras();calculate()};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderRows(lastSchedule,b.dataset.view==='extra')});$('#save-calc').onclick=()=>{localStorage.setItem('finaiEarlyPayment',JSON.stringify({params:params(),extras}));alert('Расчет сохранен в этом браузере')};try{const s=JSON.parse(localStorage.getItem('finaiEarlyPayment'));if(s){$('#amount').value=s.params.amount;$('#rate').value=s.params.annual;$('#term').value=s.params.months;$(`[name=payment-type][value=${s.params.type}]`).checked=true;extras=s.extras||[]}}catch{}renderExtras();calculate();
